630	// genFieldAccess generates IR for a field access expression (obj.field)
631	func (g *Generator) genFieldAccess(node *ast.Node) (Operand, error) {
632		if len(node.Children) == 0 {
633			return Operand{}, fmt.Errorf("field access requires object expression")
634		}
635	
636		// Generate IR for object expression
637		objOp, err := g.genExpr(node.Children[0])
638		if err != nil {
639			return Operand{}, err
640		}
641	
642		fieldName := node.Value
643	
644		// Search for field offset in known structs
645		var offset int64
646		found := false
647		for _, fields := range g.structFields {
648			for i, f := range fields {
649				if f == fieldName {
650					offset = int64(i * 8)
651					found = true
652					break
653				}
654			}
655			if found {
656				break
657			}
658		}
659		// If not found, use offset 0 as fallback
660	
661		// Emit OpFieldLoad instruction
662		result := g.newTemp()
663		g.emit(Instruction{
664			Op:   OpFieldLoad,
665			Dest: result,
666			Src1: objOp,
667			Src2: Operand{IsImm: true, ImmVal: offset},
668		})
669	
670		return result, nil
671	}
