673	// genArrayLit generates IR for array literals: [1, 2, 3]
674	func (g *Generator) genArrayLit(node *ast.Node) (Operand, error) {
675		// Generate IR for each element and emit as parameter
676		for _, elem := range node.Children {
677			op, err := g.genExpr(elem)
678			if err != nil {
679				return Operand{}, err
680			}
681			g.emit(Instruction{
682				Op:   OpParam,
683				Src1: op,
684			})
685		}
686	
687		// Create array with element count
688		result := g.newTemp()
689		g.emit(Instruction{
690			Op:   OpArrayNew,
691			Dest: result,
692			Src1: Operand{IsImm: true, ImmVal: int64(len(node.Children))},
693		})
694	
695		return result, nil
696	}
